# THE DEUTERONOMY WALK sitting 17 — CHAPTERS 22-25 (LEAN, 2026-09-26; RUN 3): THE CLAIMS of Deuteronomy 22:1-25:19, FOUR manifests for the four draft units, read off
# this sitting's one ledger, every claim LABELED (logic/MIDDOT.md's codes — I1 the a fortiori (qal wa-chomer), I2 the gezerah shavah (the verbal analogy), I3 the
# binyan av (the prototype) — CHECKED IN MIDDOT.md BEFORE THEY WERE TYPED), a machine check where the ink allows — every he_contains substring CUT FROM THE SNAPSHOT
# STORE'S OWN BYTES by the word's consonants. Claim IDs DV22- to DV25-. Written once (no file may exist; the prefixes checked absent). THE SOURCES DISTRIBUTED BY
# COMPUTATION: every spine piska to the claim whose verse range holds its head (the headless five by the ink's HEADLESS seats), every kept outside row by the verse it
# cites; every cite index name must be used by exactly the claims that own it. Sitting 16's form (write_ch19_manifest.py) over four units. RUN FROM THE REPO ROOT
# with PYTHONPATH the scratchpad.
import json, os, re, sqlite3, glob, subprocess, sys
ROOT = _ROOT
SP = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, SP)
import ch22_ink as I
DATE = I.DATE
db = sqlite3.connect(f'file:{ROOT}/torah_grok.SNAPSHOT-main-51801ca.sqlite?mode=ro', uri=True)
def cut(book, ch, v, word, nth=0):
    rows = db.execute("SELECT w.idx, w.he FROM words w JOIN verses v ON w.verse_id=v.id WHERE v.book=? AND v.chapter=? AND v.verse=? ORDER BY w.idx", (book, ch, v)).fetchall()
    plain = lambda h: ''.join(c for c in h if c != '/' and not (0x0591 <= ord(c) <= 0x05C7))
    hit = [(i, h) for i, h in rows if plain(h) == word]
    assert len(hit) > nth, (book, ch, v, word, hit)
    idx, he = hit[nth]
    piece = max(he.split('/'), key=len)
    assert len(piece) >= 4, (book, ch, v, word, he.split('/'))
    return idx, piece
def hc(ref, word, note, nth=0):
    b, cv = ref.split(' '); c, v = map(int, cv.split(':'))
    idx, sub = cut(b, c, v, word, nth)
    return {"type": "he_contains", "ref": ref, "idx": idx, "contains": sub, "note": note}
led = open(f'{ROOT}/logic/oral_triage/deu_22_25_ki_teitzei_{DATE}.md', encoding='utf-8').read().split('## CITE INDEX')[1]
CI = set(re.findall(r'^(Onkelos Deut \d+:\d+|Sifrei Devarim \d+:\d+)$', led, re.M)); assert len(CI) == 540, len(CI)
HEADV = {222: (22, 1), 236: (22, 16), 269: (24, 1), 283: (24, 19), 295: (25, 15)}
def headv(p): return I.heads[p] if I.heads[p] else HEADV[p]
KEPT = [k for k in I.OUTSIDE if k not in I.EXCLUDED]
def src(c, lo, hi):
    names = [f'Onkelos Deut {c}:{v}' for v in range(lo, hi + 1)]
    names += [f'Sifrei Devarim {p}:{r}' for p in I.PISKAOT if headv(p)[0] == c and lo <= headv(p)[1] <= hi for r in range(1, I.SPINE_ROWS[p] + 1)]
    names += [f'Sifrei Devarim {p}:{r}' for p, r in KEPT if I.CITED[(p, r)][0][0] == c and lo <= I.CITED[(p, r)][0][1] <= hi]
    for n in names: assert n in CI, n
    return '; '.join(names)
