ALL = ''.join(open(f, encoding='utf-8').read() for f in glob.glob(f'{ROOT}/logic/oral_audit/manifests/*.json')) + ''.join(open(f, encoding='utf-8').read() for f in glob.glob(f'{ROOT}/logic/units/*.yaml'))
total = 0
for uid, (pre, Cs) in M.items():
    out = f'{ROOT}/logic/oral_audit/manifests/{uid}_claims.json'
    assert not os.path.exists(out), out
    assert f'"{pre}-' not in ALL and f'[claim {pre}-' not in ALL, pre
    assert [c['id'] for c in Cs] == [f'{pre}-{n:02d}' for n in range(1, len(Cs) + 1)], uid
    for c in Cs:
        for s in c['source'].split('; '): assert s in CI, (c['id'], s)
        assert c['middah'] and c['middah'].endswith(')') and c['check']['contains'] and len(c['check']['contains']) >= 4, c['id']
    json.dump(Cs, open(out, 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
    total += len(Cs); print(f'wrote {out}: {len(Cs)} claims; the check pieces', [(c['check']['ref'], c['check']['idx'], len(c['check']['contains'])) for c in Cs])
USED = [s for _, (pre, Cs) in M.items() for c in Cs for s in c['source'].split('; ')]
assert len(USED) == len(set(USED)) and set(USED) == CI, (len(USED), sorted(CI - set(USED))[:10], sorted(set(USED) - CI)[:10])
print('claims', total, '| every CITE INDEX name used by exactly one claim:', set(USED) == CI and len(USED) == len(CI))
